ent<textarea name="message" required></textarea></label><button class="button secondary">Send comment</button></form><hr><h2>Request changes</h2><form class="form-stack" method="POST" action="{{ route('public.quotation.revision',$token) }}">@csrf<label>Your name<input name="author_name" required></label><label>Changes needed<textarea name="message" required></textarea></label><button class="button secondary">Request revision</button></form></article></section>@endif<footer class="public-footer">Secure quotation access · Do not forward this private link.</footer></x-layouts.public>
